/**
 * The AndroidManifest.xml prebuild would write, computed in memory (test-only).
 *
 * android/ is gitignored and regenerated by prebuild on every EAS build, so the
 * manifest the app ships exists only as what the config plugins do to the
 * template. This runs the same Android manifest mod chain prebuild runs - every
 * plugin app.json lists, plus the built-in ones getPrebuildConfigAsync adds
 * (allowBackup, blocked permissions, ...) - over the template's manifest, and
 * touches no file.
 *
 * TEMPLATE_MANIFEST carries the parts of the SDK 54 bare template the
 * assertions read: its <application> and <activity> and the permissions it
 * declares, the three that pass 82 blocks among them. Library manifests add
 * two of those again at Gradle merge time (expo-file-system, expo-image); only
 * a tools:node="remove" entry in this manifest takes them out of the merged one.
 */

import { getPrebuildConfigAsync } from '@expo/prebuild-config';
import { AndroidConfig, XML, type ExportedConfig } from 'expo/config-plugins';
import * as path from 'path';

type AndroidManifest = AndroidConfig.Manifest.AndroidManifest;

export const REPO_ROOT = path.resolve(__dirname, '..', '..');

export const TEMPLATE_MANIFEST = `<manifest xmlns:android="http://schemas.android.com/apk/res/android">
  <uses-permission android:name="android.permission.INTERNET"/>
  <uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE"/>
  <uses-permission android:name="android.permission.SYSTEM_ALERT_WINDOW"/>
  <uses-permission android:name="android.permission.VIBRATE"/>
  <uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE"/>
  <queries>
    <intent>
      <action android:name="android.intent.action.VIEW"/>
      <category android:name="android.intent.category.BROWSABLE"/>
      <data android:scheme="https"/>
    </intent>
  </queries>
  <application android:name=".MainApplication" android:label="@string/app_name" android:icon="@mipmap/ic_launcher" android:roundIcon="@mipmap/ic_launcher_round" android:allowBackup="true" android:theme="@style/AppTheme" android:supportsRtl="true">
    <activity android:name=".MainActivity" android:configChanges="keyboard|keyboardHidden|orientation|screenSize|screenLayout|uiMode" android:launchMode="singleTask" android:windowSoftInputMode="adjustResize" android:theme="@style/Theme.App.SplashScreen" android:exported="true">
      <intent-filter>
        <action android:name="android.intent.action.MAIN"/>
        <category android:name="android.intent.category.LAUNCHER"/>
      </intent-filter>
    </activity>
  </application>
</manifest>`;

/** Run every Android manifest mod of the project config over TEMPLATE_MANIFEST. */
export async function resolveAndroidManifest(): Promise<AndroidManifest> {
    // The mods prebuild registers live on the config next to the public fields.
    const exp = (await getPrebuildConfigAsync(REPO_ROOT, { platforms: ['android'] })).exp as ExportedConfig;
    const manifestMod = exp.mods?.android?.manifest;
    if (!manifestMod) {
        throw new Error('No Android manifest mod is registered for this project.');
    }
    const modResults = (await XML.parseXMLAsync(TEMPLATE_MANIFEST)) as unknown as AndroidManifest;
    const result = await manifestMod({
        ...exp,
        modResults,
        modRawConfig: exp,
        modRequest: {
            projectRoot: REPO_ROOT,
            // Never read: manifest mods work on modResults. A path that does
            // not exist keeps a stale local android/ out of the result.
            platformProjectRoot: path.join(REPO_ROOT, '.no-android-project'),
            modName: 'manifest',
            platform: 'android',
            introspect: false,
        },
    });
    return result.modResults;
}

/** The main <application> element's attributes. */
export function applicationAttributes(manifest: AndroidManifest): Record<string, string | undefined> {
    return AndroidConfig.Manifest.getMainApplicationOrThrow(manifest).$ as Record<string, string | undefined>;
}

/** Every <uses-permission> entry, as its attributes. */
export function usesPermissions(manifest: AndroidManifest): Record<string, string | undefined>[] {
    return (manifest.manifest['uses-permission'] ?? []).map((entry) => entry.$ as Record<string, string | undefined>);
}
